// Stop the polling loop instead of hammering Supadata forever.
const attempt = typeof $runIndex === 'number' ? $runIndex : 0;
if (attempt > 20) {
  throw new Error('Supadata job not finished after 20 polls (~100s) - aborting, no Notion page written.');
}
return $input.all();

// n8n Code node: "Split transcript" (Mode: Run Once for All Items)
// Input : one item  -> { sourceUrl, lang, content }
// Output: N items   -> { sourceUrl, lang, chunkIndex, chunkCount, words, text }
//
// Why sentences instead of characters: Supadata returns a single plain-text
// blob when text=true. Cutting it every N characters splits words and, worse,
// usually splits a sentence across two chunks, so each chunk starts mid-claim
// and the model has to guess the antecedent. Splitting on sentence boundaries
// with one sentence of overlap costs ~1% extra tokens and removes that class
// of error. 1200 words ~= 1600 English tokens, which leaves room in an 8k
// window for the prompt, the previous chunk's notes, and a 400-token answer.

const MAX_WORDS = 1200;
const OVERLAP_SENTENCES = 1;

const SENTENCE_RE = /[^.!?]+[.!?]+(?:["')\]]+)?|[^.!?]+$/g;

const words = (s) => s.trim().split(/\s+/).filter(Boolean).length;

function splitSentences(text) {
  const flat = text.replace(/\s+/g, ' ').trim();
  const parts = flat.match(SENTENCE_RE) || [flat];
  return parts.map((s) => s.trim()).filter(Boolean);
}

function chunk(text) {
  const sents = splitSentences(text);
  const chunks = [];
  let start = 0;

  while (start < sents.length) {
    let end = start;
    let count = 0;
    while (end < sents.length) {
      const w = words(sents[end]);
      // Always take at least one sentence, even if it alone exceeds the budget.
      if (count > 0 && count + w > MAX_WORDS) break;
      count += w;
      end += 1;
    }
    chunks.push({ text: sents.slice(start, end).join(' '), words: count });
    if (end >= sents.length) break;
    start = Math.max(start + 1, end - OVERLAP_SENTENCES);
  }
  return chunks;
}

const out = [];

for (const item of $input.all()) {
  const { sourceUrl, lang, content } = item.json;

  if (typeof content !== 'string' || content.trim() === '') {
    // Fail loudly here instead of writing an empty Notion page downstream.
    throw new Error(
      `Empty transcript for ${sourceUrl} (lang=${lang}) - stopping before the LLM call.`
    );
  }

  const chunks = chunk(content);

  chunks.forEach((c, i) => {
    out.push({
      json: {
        sourceUrl,
        lang,
        chunkIndex: i,
        chunkCount: chunks.length,
        words: c.words,
        text: c.text,
      },
    });
  });
}

return out;

// n8n Code node: "Merge summaries" (Mode: Run Once for All Items)
// Input : the "done" output of the Chunk loop
// Output: one item carrying every per-chunk note
//
// The chunk LLM runs inside a batch loop, so its items are not attached to the
// current item. $('Summarize chunk').all() is the documented way to collect them
// once the loop reports done.

const parts = $('Summarize chunk')
  .all()
  .map((item, i) => `Part ${i + 1}: ${String(item.json.text || '').trim()}`)
  .filter((p) => p.length > 10);

if (parts.length === 0) {
  throw new Error('No chunk summaries were produced - nothing to merge.');
}

const first = $('Prepare input').first().json;
return [
  {
    json: {
      sourceUrl: first.sourceUrl,
      lang: first.lang,
      chunkCount: parts.length,
      notes: parts.join('\n\n'),
    },
  },
];

// n8n Code node: "Validate output" (Mode: Run Once for All Items)
// Input : { text } from the merge LLM call
// Output: exactly the fields the Notion node maps
//
// The merge prompt asks for JSON. Models still wrap it in a markdown fence or
// return prose when they get confused, and the Notion node would happily write
// an empty page in that case. So: strip the fence, parse, then enforce minimum
// shape. A bad answer fails the execution instead of creating a bad note.

const sourceUrl = $('Prepare input').first().json.sourceUrl;
const lang = $('Prepare input').first().json.lang;

const fence = String.fromCharCode(96).repeat(3);

let raw = String($json.text || '').trim();
if (raw.startsWith(fence)) raw = raw.slice(fence.length).trim();
if (/^json/i.test(raw)) raw = raw.slice(4).trim();
if (raw.endsWith(fence)) raw = raw.slice(0, -fence.length).trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Model did not return valid JSON: ' + raw.slice(0, 200));
}

const title = String(parsed.title || '').trim();
const summary = String(parsed.summary || '').trim();
const takeaways = Array.isArray(parsed.takeaways)
  ? parsed.takeaways.map((t) => String(t).trim()).filter(Boolean).slice(0, 5)
  : [];

if (title.length < 8 || summary.length < 80 || takeaways.length < 2) {
  throw new Error(
    `Rejected model output (title=${title.length} chars, summary=${summary.length} chars, takeaways=${takeaways.length})`
  );
}

return [
  {
    json: {
      title: title.slice(0, 200),
      sourceUrl,
      lang,
      summary,
      takeaways: takeaways.map((t) => '• ' + t).join('\n'),
      processedAt: new Date().toISOString(),
    },
  },
];
